import{_ as p,c as e,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"卷七（文言）","description":"伊川易傳 - 卷七（文言）","frontmatter":{"title":"卷七（文言）","description":"伊川易傳 - 卷七（文言）"},"headers":[],"relativePath":"classics/yichuan/008.md","filePath":"classics/yichuan/008.md"}'),t={name:"classics/yichuan/008.md"};function s(n,a,l,c,h,o){return r(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="卷七-文言" tabindex="-1">卷七（文言） <a class="header-anchor" href="#卷七-文言" aria-label="Permalink to “卷七（文言）”">​</a></h1><p>乾文言</p><h3 id="第一段" tabindex="-1">第一段 <a class="header-anchor" href="#第一段" aria-label="Permalink to “第一段”">​</a></h3><p>“元”者，善之長也；“亨”者，嘉之會也；“利”者，義之和也；“貞”者，事之乾也。(2)君子體仁足以長人，嘉會足以合禮，利物足以和義，貞固足以乾事。君子行此四德者，故曰：“乾、元、亨、利、貞。”(3)初九曰：“潛龍勿用。”何謂也？子曰：“龍德而隱者也，不易乎世，不成乎名，遯世無悶，不見是而無悶，樂則行之，憂則違之，確乎其不可拔，潛龍也。”(4)九二曰：“見龍在田，利見大人。”何謂也？子曰：“龍德而正中者也。庸言之信，庸行之謹，閒邪存其誠，善世而不伐，德博而化，《易》曰‘見龍在田，利見大人’。君德也。”(5)九三曰：“君子終日乾乾，夕惕若厲，無咎。”何謂也？子曰：“君子進德修業。忠信所以進德也。修辭立其誠，所以居業也。知至至之，可與幾也。知終終之，可與存義也。是故居上位而不驕，在下位而不憂，故乾乾因其時而惕，雖危無咎矣。”(6)九四曰：“或躍在淵，無咎。”何謂也？子曰：“上下無常，非為邪也。進退無恆，非離群也。君子進德修業，欲及時也，故無咎。”(7)九五曰：“飛龍在天，利見大人。”何謂也？子曰：“同聲相應，同氣相求。水流溼，火就燥。雲從龍，風從虎。聖人作而萬物覩。本乎天者親上，本乎地者親下。則各從其類也。”(8)上九曰：“亢龍有悔。”何謂也？子曰：“貴而無位，高而無民，賢人在下位而無輔，是以動而有悔也。”</p><h3 id="註釋" tabindex="-1">註釋 <a class="header-anchor" href="#註釋" aria-label="Permalink to “註釋”">​</a></h3><p>(1)文言：對“文言”二字之義先儒眾說不一，一、乾坤為門戶，以文說乾坤；二、依文而言其理；三、因卦爻辭為文王所作，故曰“文言”；四、文謂文飾，以乾坤德大，故特文飾以為“文言”；五、單就卦爻辭而推衍之，故曰“文言”，等等。筆者以為當依文言理之說近實。</p><p>(2)元：開始。長：訓首，君。亨：古文字有祭祀之義，此訓為通。嘉：美。古者婚禮稱“嘉”。會：聚合。利，本指銛。“利”從刀主分，分故能裁成事物使各得宜；“利”從禾。禾二月始生，八月而熟，得時之中，如《說文》所言：“利……和然後利，從和省。”故“利”又有中和之義。義：宜。《中庸》：“義者，宜也。”《白虎通德論·情性》：“義者，宜也，斷決得中也。”貞：一說為佔問，一說為正。乾：樹乾。木旁生者為枝，正出者為乾，故“乾”有正之義，因枝葉依乾而立，故“乾”又有本之義。鄭注《禮記·月令》“羽箭乾”曰：“乾者，器之本也。”</p><p>(3)仁：凡果核之實有生氣者曰“仁”，以仁為木，案李道平、周易集解纂疏》，“仁”有“元”之義，“元”從二從人，“仁”從人從二，故在天為“元”，在人為“仁”。《釋名·釋形體》：“人，仁也；仁，生物也。”長人：猶君人，即主宰人。利物：一本作“利之”。</p><p>(4)此釋《乾》初九之爻辭。龍德：陽剛之德。《乾》卦爻辭以“龍”喻陽。隱：是釋“潛”。《乾》初九居下故曰“隱”。易：移。世：世俗。不見是：不為世人所贊同。遯：隱退。悶：煩悶。確：剛強之貌。拔：移。</p><p>(5)此釋《乾》九二爻辭。正中；《乾》九二爻居內卦正得中位。庸言：平常的言論。先儒有解“庸”為“中”者，但由下文“善世而不伐”思之。似解“庸”作平庸為妥。閒：防。善世：吳汝綸曰：“此‘善世’即善大，與‘德博’對文。”伐：自誇。化：感化。君德：即陽德，陽為君。</p><p>(6)此釋《乾》九三爻辭。進德修業：增進德性修治學業。九三過中，故曰“進德修業”。修，治。知至至之：前“至”為名詞，指到達，後“至”為動詞，指努力做到。知終終之：前“終”為名詞，指終結。後“終”為動詞，指善於停止。幾：微。《繫辭》：“幾者，動之微，吉之先見者也。”上位：九三居內卦之上。下位：指九三居外卦之下。</p><p>(7)此釋《乾》卦九四爻辭。上下：言爻位。四為陰位，上可以承君，下可以應初，故曰“上下”。邪，邪枉。九四以陽居陰失位故曰“邪”。進退：言爻，九四上進可居五，下退可居三。群：類。此指陽類。《乾》六爻皆陽，故六陽稱“群”。</p><p>(8)此釋《乾》九五爻辭。同聲相應，同氣相求：乾坤陰陽各以類相應相求。乾為純陽，故曰“同聲”、“同氣”。應，感應。求，追求。雲從龍：雲，水氣。龍，水物。雲龍同類，感氣相致，故“雲從龍”。風從虎：風為震動之氣，虎是威猛之獸，虎嘯風生，風與虎也同氣類，故曰“風從虎”。作：起。覩：見。親：親附。</p><p>(9)此釋《乾》上九爻辭，與《繫辭上》八章同。注見上。</p><h3 id="第二段" tabindex="-1">第二段 <a class="header-anchor" href="#第二段" aria-label="Permalink to “第二段”">​</a></h3><p>“潛龍勿用”，下也；“見龍在田”，時舍也；“終日乾乾”，行事也；“或躍中淵”，自試也；“飛龍在天”，上治也；“亢龍有悔”，窮之災也；乾元“用九”，天下治也。①“潛龍勿用”，陽氣潛藏；“見龍在田”，天下文明；“終日乾乾”，與時偕行；“或躍在淵”，乾道乃革；“飛龍在天”，乃位乎天德；“亢龍有悔”，與時偕極；乾元“用九”，乃現天則。②乾“元”者，始而亨者也；“利貞”者，性情也。乾始能以美利利天下，不言所利，大矣哉，大哉乾乎，剛健中正，純粹精也。六爻發揮，旁通情也，時乘六龍，以御天也。雲行雨施，天下平也。③君子以成德為行，日可見之行也。“潛”之為言也，隱而未見，行而未成，是以君子弗用也。④君子學以聚之，問以辯之，寬以居之，仁以行之。《易》曰：“見龍在田，利見大人。”君德也。⑤九三重剛而不中，上不在天，下不在田，故乾乾因其時而惕，雖危“無咎”矣。⑥九四重剛而不中，上不在天，下不在田，中不在人，故“或”之，或之者，疑之也。故“無咎”。⑦夫“大人”者，與天地合其德，與日月合其明，與四時合其序，與鬼神合其吉凶。先天而天弗違，後天而奉天時，天且弗違，而況於人乎！況於鬼神乎！⑧“亢”之為言也，知進而不知退，知存而不知亡，知得而不知喪，其唯聖人乎！知進退存亡而不失其正者，其唯聖人乎！⑨</p><h3 id="註釋-1" tabindex="-1">註釋 <a class="header-anchor" href="#註釋-1" aria-label="Permalink to “註釋”">​</a></h3><p>①此以人事釋《乾》爻辭。下，釋“潛”，指初九之陽居下，其位卑賤。舍，此字古人多解；有謂“舍”通“舒”者，然案之《井》卦初六爻“舊井無禽”，《象》曰：“時舍也。”顯然《象》解“舍”為棄，由《文言》稱“雲從龍”，可知龍本應在天為得時，今在田而曰“時舍也”，可知此處亦解“舍”為棄。試：驗。窮：極。</p><p>②此以天道釋《乾》爻辭。陽氣潛藏：初九一陽居下，故象徵陽氣潛於下而未動。天下文明：九二陽氣上升，故天下文彩光明。文明，文彩光明。偕：俱。乾道乃革：《雜卦》：“革，去故也。”九四爻居上卦之始，故“乾道乃革”。位乎天德：陽至九五而處尊位。天德：指九五天位。極：終極。天則：天象法則。</p><p>③此申《乾·彖》意。即釋《乾》卦卦辭。性情：一本作“情性”。性，天性。情，是情意。人稟陰陽而生故有性情。《白虎通德論·情性》：“情性者，何謂也？性者，陽之施。情者，陰之化也。人稟陰陽之氣而生，故內懷五性六情。”能：而。美利：美善。此指生物。即雲行雨施以生物。剛健中正：《乾》六爻皆陽故“剛健”，二五為中，初、三、五以陽居陽得位故曰正。《乾》六爻中九五居中得正，故曰中正。純粹精：此卦全陽不雜故曰“純粹精”。色不雜曰純，米不雜曰粹，米至細曰精。揮：動，散。一本作輝，二者音同義通假。旁：遍。通：通達。《繫辭》：“往來不窮謂之通。”六龍：六位之龍。御：駕馬使行。雲行雨施：指天之功用。雲氣流行，雨澤佈施。平：均勻平和。</p><p>④此釋初九爻辭。成德：已成就的道德。弗：不。</p><p>⑤此釋九二爻辭。聚：會。辯：一本作辨。二者通，有明辨之義。寬：弘廣。</p><p>⑥此釋九三爻辭。重剛：九三居內卦乾之終，上與外卦乾之初相接，乾為剛，故曰“重剛”。不中：指九三不處二五之位，爻以二五為中。上不在天，指往上不在九五爻。天，指九五爻。此爻辭為“飛龍在天”。田，指九二爻。此爻辭為“見龍在田”。</p><p>⑦此釋九四爻辭。中不在人：九四居卦中間而不處人之正位。中，指居卦之中。人，指人位。卦三、四爻為人位，三與二相比，故三附於地處人之正位。四雖處人位，但元於地而近天，非人所處，故九四“中不在人”。</p><p>⑧此釋九五爻辭。大人：此指九五而言，九五有“利見大人”之辭。大人指聖明德備之人。《周易》中有周人五號：帝，天稱。王，美稱。天子，爵號。大君，興感行異。大人，聖明德備。序：次序。鬼神：陰陽之氣屈伸變化，天時：四時。</p><p>⑨此釋上九爻辭。上“聖人”王肅本作“愚人”，案愚人、聖人相對為文，故王肅本極是。唯：通惟，猶是。《文選·甘泉賦》李善注：“惟，是也。”</p><p>坤文言</p><p>坤至柔而動也剛，至靜而德方，後得主而有常，含萬物而化光。坤道其順乎，承天而時行。①積善之家必有餘慶，積不善之家必有餘殃。臣弒其君，子弒其父，非一朝一夕之故，其所由來者漸矣。由辯之不早辯也。《易》曰：“履霜，堅冰至。”蓋言順也。②“直”其正也，“方”其義也。君子敬以直內，義以方外，敬義立而德不孤。“直方大，不習無不利。”則不疑其所行也。③陰雖有美，“含”之以從王事，弗敢成也。地道也，妻道也，臣道也。地道“無成”而代“有終”也。④天地變化，草木蕃，天地閉，賢人隱。《易》曰：“括囊，無咎無譽。”蓋言謹也。⑤君子“黃”中通理，正位居體，美在其中，而暢於四支，發於事業，美之至也！⑥陰疑於陽必戰，為其嫌於無陽也。故稱“龍”焉猶未離其類也，故稱“血”焉。夫“玄黃”者，天地之雜也，天玄而地黃。⑦</p><h3 id="註釋-2" tabindex="-1">註釋 <a class="header-anchor" href="#註釋-2" aria-label="Permalink to “註釋”">​</a></h3><p>①此釋《坤》卦卦辭。至柔：《坤》六爻皆陰，純陰和順，故曰“至柔”。德方：先儒多解“德”為德性，但由上文“動也剛”思之，“德”與“動”對文，似以作“得”解為妥。方，方正。古人以圓說明天體運動，以方正說明地之靜止，故稱“方”。“方”釋經文中“貞”。後得主：經文中有“先迷後得主”，其意為：先迷惑後找到主人。傳文釋為“後得主而有常”。顯然與經文之義不同。常，規律，常道。化光：化育廣大。古“化”有生義。光，廣。</p><p>②此釋《坤》初六爻辭“履霜，堅冰至”。原意為：踏霜之時，當知堅冰之日將至。弒：試殺。《白虎通德論·誅伐篇》：“弒者，何謂也？弒者，試也。欲言臣子殺其君父不敢卒，候間司事，可稍稍殺弒之。”辯：即辨。漸：漸進，即由小而大。《坤》初六居下，陰小而始動，不善之積，故曰“漸”。陰為不善。順：順從。《春秋繁露·基義篇》引作“遜”。</p><p>③此釋《坤》六二爻辭。正：從止一，其義守一以止。六二以陰爻居陰位故為“正”。義：宜。六二居中，故為“義”。內：內心。外：</p><p>④此釋《坤》六三爻辭“含章可貞，或從王事，無成有終”。經文原意為：蘊含章美可以守正，跟從大王做事，雖不成功，但有好的結果。含：含藏。六三是以陰居陽位，故為“含章”。陽為章美。</p><p>⑤此釋《坤》六四爻辭。蕃：草木茂盛。天地閉：天地不交通。六四居上下卦之間，上下皆坤，故上下不交而閉塞。閉，塞。括囊：束扎口袋。</p><p>⑥此釋《坤》六五爻辭“黃裳元吉”。黃中：六五居中，而有中德。古代以土色為黃，土在五行中居中，故黃色即中色，黃有中之義。正位居體：六五以陰居陽之正位。五為陽之正位，六五陰爻為體。支：肢，指四肢。發：見。</p><p>⑦此釋《坤》上六爻辭“龍戰於野，其血玄黃”。陰：《坤》上六為陰。疑：即凝，有交結、聚合之義。嫌：疑。未離類：《坤》上六雖稱龍，但未離開陰類。玄黃：天地之正色，此指陰陽相遇兩敗俱傷。玄：黑中有赤。</p>',36)])])}const f=p(t,[["render",s]]);export{_ as __pageData,f as default};
